steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issue(identifier: \"WEB-1\") { id identifier number team { id name prefix } state { name } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issues(first: 10, filter: { identifier: { eq: \"WEB-1\" } }) { nodes { id identifier number title team { id key name } state { name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { teams { nodes { id key name } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issues(first: 10, filter: { team: { id: { eq: \"t-web\" } } }) { nodes { id identifier number title team { id key name } state { name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-web-1\", input: { number: 100 }) { success issue { id identifier number } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"IssueUpdateInput\") { inputFields { name type { name kind ofType { name } } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"IssueCreateInput\") { inputFields { name type { name kind } } } }"
  }'
